mapper.select:
SELECT * FROM ( SELECT ROWNUM AS RN, T.* FROM ( SELECT R.RSD_BRD_ID, R.OPEN_YN, R.REQ_STATUS, B.BRD_CODE, B.BLDG_ID, B.MBR_CD, B.BRD_TITL_NM, B.BRD_CONT, B.BRD_PBLS_DTM, B.BRD_VW_CNT, B.BRD_MOD_DTM, B.BRD_DEL_YN, R.RSD_BRD_DEL_YN, M.MBR_NNM, R.REPLY_CONT FROM RESIDENT_BOARD R JOIN BOARD B ON R.RSD_BRD_ID = B.BRD_NO JOIN MEMBER M ON B.MBR_CD = M.MBR_CD JOIN BUILDING H ON R.BLDG_ID = H.BLDG_ID JOIN TENANCY T ON H.RENTAL_PTY_ID = T.RENTAL_PTY_ID
AND R.RSD_BRD_DEL_YN = 'N' AND B.BRD_DEL_YN = 'N'
AND B.BLDG_ID = #{search.bldgId}
AND TO_CHAR(B.BRD_PBLS_DTM, 'YYYY-MM-DD') >= #{search.searchStartDate}
AND TO_CHAR(B.BRD_PBLS_DTM, 'YYYY-MM-DD') <= #{search.searchEndDate}
AND B.BRD_CODE = #{search.brdCode}
AND R.OPEN_YN = #{search.openYn}
AND R.REQ_STATUS = #{search.reqStatus}
AND B.BRD_TITL_NM LIKE '%'||#{search.searchWord}||'%'
AND B.BRD_CONT LIKE '%'||#{search.searchWord}||'%'
AND ( B.BRD_TITL_NM LIKE '%'||#{search.searchWord}||'%' OR B.BRD_CONT LIKE '%'||#{search.searchWord}||'%' )
AND B.MBR_CD = #{search.loginMbrCd}
ORDER BY B.BRD_PBLS_DTM DESC ) T WHERE ROWNUM <= #{paging.lastRecordIndex} ) WHERE RN >= #{paging.firstRecordIndex}

    SELECT COUNT(*)
      FROM RESIDENT_BOARD R
      JOIN BOARD B ON R.RSD_BRD_ID = B.BRD_NO
    
      AND R.RSD_BRD_DEL_YN = 'N'
      AND B.BRD_DEL_YN     = 'N'
      
        AND B.BLDG_ID  = #{search.bldgId}
      
      
        AND B.BRD_CODE = #{search.brdCode}
      
      
        AND TO_CHAR(B.BRD_PBLS_DTM, 'YYYY-MM-DD') >= #{search.searchStartDate}
      
      
        AND TO_CHAR(B.BRD_PBLS_DTM, 'YYYY-MM-DD') <= #{search.searchEndDate}
      
      
        
          AND R.OPEN_YN = #{search.openYn}
        
      
      
        AND R.REQ_STATUS = #{search.reqStatus}
      
      
        
          
            AND B.BRD_TITL_NM LIKE '%'||#{search.searchWord}||'%'
          
          
            AND B.BRD_CONT   LIKE '%'||#{search.searchWord}||'%'
          
          
            AND (
              B.BRD_TITL_NM LIKE '%'||#{search.searchWord}||'%'
              OR B.BRD_CONT   LIKE '%'||#{search.searchWord}||'%'
            )
          
        
      
		
		  AND B.MBR_CD = #{search.loginMbrCd}

mapper.update:
UPDATE BOARD
   SET BRD_TITL_NM  = #{rsdBrdTitl},
       BRD_CONT      = #{rsdBrdCont},
       BRD_MOD_DTM   = #{rsdBrdModDate}
 WHERE BRD_NO       = #{rsdBrdId}

UPDATE RESIDENT_BOARD
   SET OPEN_YN      = #{openYn},
       RSD_BRD_MOD_DTM = SYSDATE,
       
     	 REQ_STATUS = #{reqStatus}
 	   
 WHERE RSD_BRD_ID   = #{rsdBrdId}

UPDATE BOARD
   SET BRD_DEL_YN = 'Y'
 WHERE BRD_NO     = #{rsdBrdId}

UPDATE RESIDENT_BOARD
   SET RSD_BRD_DEL_YN = 'Y'
 WHERE RSD_BRD_ID      = #{rsdBrdId}

mapper.select:
select count(*)
from building a
inner join tenancy b on (a.rental_pty_id = b.rental_pty_id)
inner join member c on (b.mbr_cd = c.mbr_cd)
where a.bldg_id = #{bldgId}
and c.mbr_cd= #{mbrCd}
